<script lang="ts">
    import type { Snippet } from "svelte";

    /**
     * @description
     * A simple dialog component using the native `<dialog>` element.
     * For more features (buttons, scrim control, etc.), use `<Modal>` instead.
     * Uses modal tokens for styling (background, border, padding, shadow, etc.).
     * @example
     * <Dialog bind:open={showDialog} title="Confirm">
     *     <p>Are you sure?</p>
     * </Dialog>
     */
    let {
        open = $bindable(false),
        title,
        children,
        onclose,
    }: {
        /** Whether the dialog is open (bindable) */
        open?: boolean;
        /** Optional title for the dialog header */
        title?: string;
        /** Dialog content */
        children: Snippet;
        /** Callback when dialog closes */
        onclose?: () => void;
    } = $props();

    let dialogEl: HTMLDialogElement | null = $state(null);

    function handleClose() {
        open = false;
        onclose?.();
    }

    function handleCancel(e: Event) {
        handleClose();
    }

    $effect(() => {
        if (open && dialogEl && !dialogEl.open) {
            dialogEl.showModal();
        } else if (!open && dialogEl?.open) {
            dialogEl.close();
        }
    });
</script>

<dialog
    bind:this={dialogEl}
    class="Dialog"
    onclose={handleClose}
    oncancel={handleCancel}
>
    {#if title}
        <header class="DialogHeader">
            <h4>{title}</h4>
        </header>
    {/if}
    <div class="DialogContent">
        {@render children()}
    </div>
</dialog>

<style>
    .Dialog {
        margin: auto;
        padding: 0;
        border: var(--modal-border-size) var(--modal-border-style) var(--modal-border-color);
        width: var(--modal-width, fit-content);
        min-width: var(--modal-min-width, auto);
        border-radius: var(--modal-border-radius, var(--surface-border-radius));
        background: var(--modal-background, var(--surface-background));
        color: var(--text-color-p);
        max-width: min(
            var(--modal-max-width, 40rem),
            calc(100svw - 2rem - env(safe-area-inset-left, 0px) - env(safe-area-inset-right, 0px))
        );
        max-height: min(
            var(--modal-max-height, 80svh),
            calc(100svh - 2rem - env(safe-area-inset-top, 0px) - env(safe-area-inset-bottom, 0px))
        );
        box-shadow: var(--modal-shadow, var(--surface-shadow));
    }

    .Dialog[open] {
        display: grid;
        grid-template-rows: auto 1fr;
        opacity: 1;
        translate: 0 0;
        transition:
            opacity var(--transition-duration-fast) ease-out,
            translate var(--transition-duration-fast) ease-out,
            display var(--transition-duration-fast) allow-discrete,
            overlay var(--transition-duration-fast) allow-discrete;
    }

    .Dialog[open]::backdrop {
        opacity: 1;
        transition:
            opacity var(--transition-duration-fast) ease-out,
            display var(--transition-duration-fast) allow-discrete,
            overlay var(--transition-duration-fast) allow-discrete;
    }

    @starting-style {
        .Dialog[open] {
            opacity: 0;
            translate: 0 var(--space-xs);
        }
        .Dialog[open]::backdrop {
            opacity: 0;
        }
    }

    @media (prefers-reduced-motion: reduce) {
        .Dialog,
        .Dialog::backdrop {
            transition: none;
        }
    }

    .DialogHeader {
        padding: var(--modal-padding-block) var(--modal-padding-inline);
        border-bottom: var(--modal-border-size) var(--modal-border-style) var(--modal-border-color);
    }

    .DialogHeader h4 {
        margin: 0;
        font-size: var(--font-size-h5);
        font-weight: var(--font-weight-semibold);
        color: var(--text-color-heading);
    }

    .DialogContent {
        padding: var(--modal-padding-block) var(--modal-padding-inline);
        overflow: auto;
    }
</style>
